mapper.select:
select m.`id`, m.`user_id` as userId, COALESCE(NULLIF(u.`display_name`,''), u.`username`) as name, m.`info` as content, date_format(m.`time`,'%Y-%m-%d %H:%i:%s') as "time" from `message` m left join `users` u on m.`user_id` = u.`id`
m.`id` = #{msgId}
and m.`user_id` = #{userId}
order by m.`id` desc limit 200
